<?php
namespace Tests\Feature;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class SystemHealthTest extends TestCase{use RefreshDatabase;public function test_readiness_checks_dependencies_and_sets_security_headers():void{$this->getJson('/api/v1/health')->assertOk()->assertJsonPath('data.status','ok')->assertHeader('X-Content-Type-Options','nosniff')->assertHeader('X-Frame-Options','DENY');}public function test_only_admin_can_view_detailed_health():void{$this->actingAs(User::factory()->create(),'sanctum')->getJson('/api/v1/admin/system-health')->assertForbidden();$this->actingAs(User::factory()->create(['is_admin'=>true]),'sanctum')->getJson('/api/v1/admin/system-health')->assertOk()->assertJsonPath('data.checks.database',true);}}
